import time

def timer_decorator(func):
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"Tempo de execução: {end_time - start_time:.4f} segundos")
        return result
    return wrapper

@timer_decorator
def ordenar_por_comprimento(lista):
