import time

def tempo_execucao(func):
    def wrapper(*args, **kwargs):
        inicio = time.time()
        resultado = func(*args, **kwargs)
        fim = time.time()
        print(f'Tempo de execução: {fim - inicio:.6f} segundos')
        return resultado
    return wrapper

@tempo_execucao
def ordenar_dicionarios(lista, campo):
    return sorted(lista, key=lambda d: d[campo])

# Exemplo de uso:
lista_dicionarios = [
    {'nome': 'Alice', 'idade': 30},
    {'nome': 'Bob', 'idade': 25},
    {'nome': 'Charlie', 'idade': 35}
]
resultado = ordenar_dicionarios(lista_dicionarios, 'idade')
