def fibonacci(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

def maior_unico_recursivo(lista):
    if not lista:
        raise ValueError('A lista não pode estar vazia.')
    if len(lista) == 1:
        return lista[0]
    else:
        maior_sublista = maior_unico_recursivo(lista[1:])
        return max(lista[0], maior_sublista)

# Para garantir que o resultado final seja único:
def maior_unico(lista):
    maior = maior_unico_recursivo(lista)
    return maior if lista.count(maior) == 1 else set(filter(lambda x: x == maior, lista))

